 static void counts(JSONObject snap)throws JSONException{JSONObject days=new JSONObject(),archived=new JSONObject();int active=0;JSONArray memories=snap.getJSONArray("memories");for(int i=0;i<memories.length();i++){JSONObject m=memories.getJSONObject(i);boolean a=m.optBoolean("archived");if(!a)active++;String d=m.optString("date");if(d.length()>=10){JSONObject out=a?archived:days;String key=d.substring(0,10);out.put(key,out.optInt(key)+1);}}snap.put("memoryDays",days).put("archivedMemoryDays",archived).put("activeMemories",active).put("totalMemories",memories.length());}
