  synchronized(this){Set<String> present=new HashSet<>();for(int i=0;i<manifest.length();i++)present.add(manifest.getJSONObject(i).getString("name"));List<String> removed=new ArrayList<>();Iterator<String> known=state.getJSONObject("files").keys();while(known.hasNext()){String key=known.next();if(!present.contains(key))removed.add(key);}for(String key:removed){File stale=safeFile(key);if(stale.exists()&&!stale.delete())throw new IOException("Cannot remove obsolete mirror file");state.getJSONObject("files").remove(key);}save();}
